TreeMap<String, Integer> accounts = new TreeMap<>();
accounts.put("ACC-100", 50000);
accounts.put("ACC-200", 75000);
accounts.put("ACC-300", 120000);
accounts.put("ACC-400", 200000);
accounts.put("ACC-500", 500000);

// ═══ CLOSEST-MATCH METHODS ═══
accounts.floorKey("ACC-250");    // "ACC-200" (greatest ≤ 250)
accounts.ceilingKey("ACC-250");  // "ACC-300" (smallest ≥ 250)
accounts.lowerKey("ACC-300");    // "ACC-200" (greatest < 300, strictly less)
accounts.higherKey("ACC-300");   // "ACC-400" (smallest > 300, strictly greater)

accounts.floorEntry("ACC-250"); // Entry(ACC-200, 75000)
accounts.firstEntry();           // Entry(ACC-100, 50000)
accounts.lastEntry();            // Entry(ACC-500, 500000)
accounts.pollFirstEntry();       // removes AND returns Entry(ACC-100, 50000)

// ═══ RANGE VIEWS (backed by original!) ═══
SortedMap<String, Integer> head = accounts.headMap("ACC-300");
// {ACC-100=50000, ACC-200=75000} — all BEFORE ACC-300 (exclusive)

SortedMap<String, Integer> tail = accounts.tailMap("ACC-300");
// {ACC-300=120000, ACC-400=200000, ACC-500=500000} — FROM ACC-300 (inclusive)

SortedMap<String, Integer> sub = accounts.subMap("ACC-200", "ACC-400");
// {ACC-200=75000, ACC-300=120000} — [ACC-200, ACC-400) exclusive upper

// Inclusive bounds:
NavigableMap<String, Integer> subInclusive = accounts.subMap("ACC-200", true, "ACC-400", true);
// {ACC-200=75000, ACC-300=120000, ACC-400=200000} — both inclusive!

// Views are BACKED:
head.put("ACC-050", 10000);  // appears in BOTH head AND original accounts!
