package com.bank.navigable;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class NavigableMapTest {

    TreeMap<Integer, String> balances = new TreeMap<>(Map.of(
        10000, "LOW", 50000, "MEDIUM", 100000, "HIGH", 500000, "PREMIUM"));

    @Test
    void floorAndCeiling() {
        assertThat(balances.floorKey(75000)).isEqualTo(50000);    // ≤ 75K
        assertThat(balances.ceilingKey(75000)).isEqualTo(100000); // ≥ 75K
    }

    @Test
    void lowerAndHigher() {
        assertThat(balances.lowerKey(50000)).isEqualTo(10000);    // < 50K (strictly)
        assertThat(balances.higherKey(50000)).isEqualTo(100000);  // > 50K (strictly)
    }

    @Test
    void rangeView_backed() {
        NavigableMap<Integer, String> highBalances = balances.tailMap(100000, true);
        assertThat(highBalances).containsKeys(100000, 500000);

        balances.put(200000, "VERY_HIGH");
        assertThat(highBalances).containsKey(200000);  // view reflects change!
    }

    @Test
    void subMap_range() {
        SortedMap<Integer, String> mid = balances.subMap(50000, 500000);
        assertThat(mid.keySet()).containsExactly(50000, 100000);
        // [50000, 500000) — 500000 excluded!
    }

    @Test
    void pollFirst_removesSmallest() {
        TreeMap<Integer, String> copy = new TreeMap<>(balances);
        Map.Entry<Integer, String> smallest = copy.pollFirstEntry();
        assertThat(smallest.getKey()).isEqualTo(10000);
        assertThat(copy).doesNotContainKey(10000);  // removed!
    }
}
